// Nivel 1: extraer el mensaje de RabbitMQ
const mensaje = JSON.parse($input.item.json.content);

// Nivel 2: extraer los datos de Open-Meteo
const content = JSON.parse(mensaje.content);

const date = mensaje.date;
const dateForFile = date.replace(/-/g, '_');

// Convertir a formato largo: una fila por hora
const times = content.hourly.time;
const variables = Object.keys(content.hourly).filter(k => k !== 'time');

const rows = times.map((time, i) => {
  const row = { datetime: time, source: 'openmeteo', date: date };
  variables.forEach(v => {
    row[v] = content.hourly[v][i];
  });
  return row;
});

return [{
  json: {
    source: mensaje.source,
    date: date,
    path: `openmeteo/${dateForFile}.json`,
    content: JSON.stringify(rows)
  }
}];

// Nivel 1: extraer el mensaje de RabbitMQ
const mensaje = JSON.parse($input.item.json.content);

// Nivel 2: el content es otro JSON con campo "data"
const nivel2 = JSON.parse(mensaje.content);

// Nivel 3: el CSV real está en nivel2.data
const csvText = nivel2.data;

const date = mensaje.date;
const dateForFile = date.replace(/-/g, '_');

// Parsear CSV con separador ";" y saltos de línea Windows
const lines = csvText.trim().split(/\r?\n/);
const headers = lines[0].split(';').map(h => h.trim());

const rows = [];
for (let i = 1; i < lines.length; i++) {
  if (!lines[i].trim()) continue;
  const values = lines[i].split(';').map(v => v.trim());
  const row = {};
  headers.forEach((h, idx) => {
    row[h] = values[idx] ?? null;
  });
  row.source = 'madrid';
  row.date = date;
  rows.push(row);
}

return [{
  json: {
    source: mensaje.source,
    date: date,
    path: `madrid/${dateForFile}.json`,
    content: JSON.stringify(rows)
  }
}];
